import { prisma } from '../../infrastructure/database/prisma';
import argon2 from 'argon2';
import jwt from 'jsonwebtoken';
import { env } from '../../config/env';
export class AuthService {
    async register(data) {
        const exists = await prisma.user.findFirst({ where: { OR: [{ email: data.email }, { phone: data.phone }] } });
        if (exists)
            throw new Error('User exists');
        const passwordHash = await argon2.hash(data.password);
        const user = await prisma.user.create({ data: { email: data.email, phone: data.phone, firstName: data.firstName, lastName: data.lastName, passwordHash, role: 'CUSTOMER' } });
        return this.issueTokens(user);
    }
    async login(identifier, password) {
        const user = await prisma.user.findFirst({ where: { OR: [{ email: identifier }, { phone: identifier }] } });
        if (!user || !user.passwordHash)
            throw new Error('Invalid credentials');
        const ok = await argon2.verify(user.passwordHash, password);
        if (!ok)
            throw new Error('Invalid credentials');
        return this.issueTokens(user);
    }
    issueTokens(user) {
        const access = jwt.sign({ sub: user.id, role: user.role }, env.JWT_SECRET, { expiresIn: '15m' });
        const refresh = jwt.sign({ sub: user.id, role: user.role }, env.JWT_REFRESH_SECRET, { expiresIn: '7d' });
        return { access, refresh, user: { id: user.id, email: user.email, phone: user.phone, role: user.role } };
    }
}
export const authService = new AuthService();
